# Generated by build.py from recipe.yml for recipe coaps-serve-over-dtls. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'config', 'locked', 'open', 'psk' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'config/sensor.json'), "{`"interval`":60}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'locked/sensor.json'), "{`"interval`":60}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'open/sensor.json'), "{`"interval`":60}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'psk/sensor.json'), "{`"interval`":60}`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'config', '--cert', 'server.pem', '--key', 'server.key', 'coaps://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -m 10 --cacert server.pem coaps://127.0.0.1:8080/sensor.json } finally { Stop-Process $server0 }
